    mod.events:on("map.entered", function(ev)
      local h = ev and hooks[ev.mapId]
      if not (h and h.onEnter) then return end
      local ow = mod.world and mod.world.overworld and mod.world:overworld()
      if ow and ow.vm then ow.vm:start(h.onEnter) end
    end)
    mod.events:on("world.stepped", function(ev)
      local h = ev and hooks[ev.mapId]
      if not (h and h.onStep) then return end
      for _, c in ipairs(h.onStep) do
        if c.x == ev.x and c.y == ev.y then
          local ow = mod.world and mod.world.overworld and mod.world:overworld()
          if ow and ow.vm then
            ow.vm:start(c.key)
            ow.heldDir = nil
          end
          return
        end
      end
    end)
    mod.events:on("battle.ended", function(ev)
      if not ev or (ev.result ~= "win" and ev.result ~= "caught") then return end
      local ow = mod.world and mod.world.overworld and mod.world:overworld()
      if not (ow and ow.map and ow.vm) then return end
      local h = hooks[ow.map.id]
      if h and h.onVictory then ow.vm:start(h.onVictory) end
    end)
  end

