  -- Cutscene themes held across a warp (music.select hook)
  do
    local hold = {
      ["OAKS_LAB"] = "Music_ProfOak",
    }
    local playing = nil
    mod.hooks:wrap("music.select", function(next, chosen, ctx)
      local want = ctx and ctx.reason == "map" and ctx.mapId
        and hold[ctx.mapId] or nil
      if want and playing == want then
        -- already playing: hand the label straight back so
        -- Music.play's dedupe leaves the song alone
        return next(want, ctx)
      end
      local out2 = next(chosen, ctx)
      if out2 ~= nil then playing = out2 end
      return out2
    end)
  end

  -- Red's Pokedex rating over Gold's (special ProfOaksPCBoot)
  do
    local COMPLETION = "mod:OAKS_LAB_DEX_COMPLETION"
    local TIERS = {
      { max = 9, sfx = "Sfx_DexFanfareLessThan20", text = "mod:OAKS_LAB_DEX_RATING_00" },
      { max = 19, sfx = "Sfx_DexFanfareLessThan20", text = "mod:OAKS_LAB_DEX_RATING_01" },
      { max = 29, sfx = "Sfx_DexFanfare2049", text = "mod:OAKS_LAB_DEX_RATING_02" },
      { max = 39, sfx = "Sfx_DexFanfare2049", text = "mod:OAKS_LAB_DEX_RATING_03" },
      { max = 49, sfx = "Sfx_DexFanfare2049", text = "mod:OAKS_LAB_DEX_RATING_04" },
      { max = 59, sfx = "Sfx_DexFanfare5079", text = "mod:OAKS_LAB_DEX_RATING_05" },
      { max = 69, sfx = "Sfx_DexFanfare5079", text = "mod:OAKS_LAB_DEX_RATING_06" },
      { max = 79, sfx = "Sfx_DexFanfare5079", text = "mod:OAKS_LAB_DEX_RATING_07" },
      { max = 89, sfx = "Sfx_DexFanfare80109", text = "mod:OAKS_LAB_DEX_RATING_08" },
      { max = 99, sfx = "Sfx_DexFanfare80109", text = "mod:OAKS_LAB_DEX_RATING_09" },
      { max = 109, sfx = "Sfx_DexFanfare80109", text = "mod:OAKS_LAB_DEX_RATING_10" },
      { max = 119, sfx = "Sfx_DexFanfare140169", text = "mod:OAKS_LAB_DEX_RATING_11" },
      { max = 129, sfx = "Sfx_DexFanfare170199", text = "mod:OAKS_LAB_DEX_RATING_12" },
      { max = 139, sfx = "Sfx_DexFanfare200229", text = "mod:OAKS_LAB_DEX_RATING_13" },
      { max = 149, sfx = "Sfx_DexFanfare230Plus", text = "mod:OAKS_LAB_DEX_RATING_14" },
      { max = 255, sfx = "Sfx_DexFanfare230Plus", text = "mod:OAKS_LAB_DEX_RATING_15" },
    }
    mod.hooks:wrap("script.command", function(next, ctx, name, args, cmd)
      if name ~= "special" then return next(ctx, name, args, cmd) end
      local id = cmd and (tonumber(cmd.id)
        or (type(cmd.args) == "table" and tonumber(cmd.args[1])))
      if id ~= 100 then return next(ctx, name, args, cmd) end
      local vm = ctx and ctx.vm
      -- no vm, no text table: fall back to Gold's rather than show nothing
      if not (vm and vm.showRaw and vm.text) then
        return next(ctx, name, args, cmd)
      end
      local sp = vm.specials or {}
      local save = sp.save and sp.save() or nil
      local dex = save and save.pokedex
      local seen, owned = 0, 0
      for _, has in pairs((dex and dex.seen) or {}) do
        if has then seen = seen + 1 end
      end
      for _, has in pairs((dex and dex.caught) or {}) do
        if has then owned = owned + 1 end
      end
      local body = vm.text[COMPLETION]
      if body then
        body = body:gsub("{SEEN}", string.format("%3d", seen))
        body = body:gsub("{OWNED}", string.format("%3d", owned))
        vm:showRaw(body)
      end
      local row = TIERS[#TIERS]
      for i = 1, #TIERS do
        if owned <= TIERS[i].max then row = TIERS[i] break end
      end
      -- prof_oaks_pc.asm: WaitSFX, PlaySFX, then the rating box
      if coroutine.running() then coroutine.yield({ kind = "waitsfx" }) end
      if sp.playSfxNamed then sp.playSfxNamed(row.sfx) end
      local rated = vm.text[row.text]
      if rated then vm:showRaw(rated, nil, nil, true) end
      -- swallow the vanilla special; nil means "no jump"
      return nil
    end)
  end

  -- Running Shoes (movement.speed hook, gated on item ownership)
  mod.hooks:wrap("movement.speed", function(next, frames, ctx)
    if not ctx or ctx.surfing then return next(frames, ctx) end
    local save = ctx.save
    local has = save and save.inventory and (save.inventory["RUNNING_SHOES"] or 0) > 0
    if not has then return next(frames, ctx) end
    local input = ctx.input
    if not (input and input.isDown and input:isDown("b")) then return next(frames, ctx) end
    return next(math.max(1, math.floor(frames / 2)), ctx)
  end)

  -- Collision shadow for warps on passthrough-compiled maps
  -- (key is y * 1024 + x, the same cell key Map._warpAt uses)
  do
    local _passColl = {
      -- DIGLETTS_CAVE: (3,3)->0x7d (17,3)->0x7d (15,5)->0x7d (5,31)->0x7d (3,33)->0x7d (17,33)->0x7d
      ["DIGLETTS_CAVE"] = { [3075] = 0x7d, [3089] = 0x7d, [5135] = 0x7d, [31749] = 0x7d, [33795] = 0x7d, [33809] = 0x7d },
      -- VICTORY_ROAD: (0,27)->0x71
      ["VICTORY_ROAD"] = { [27648] = 0x71 },
    }
    mod.events:on("map.entered", function(ev)
      local map = ev and ev.map
      local cells = ev and ev.mapId and _passColl[ev.mapId]
      if type(map) ~= "table" or not cells then return end
      -- One instance is only ever shadowed once; a fresh
      -- map load builds a fresh Map and re-installs.
      if map._passCollShadowed then return end
      local base = map.cellCollision
      if type(base) ~= "function" then return end
      map._passCollShadowed = true
      map.cellCollision = function(self, cx, cy)
        local hit = cells[cy * 1024 + cx]
        if hit then return hit end
        return base(self, cx, cy)
      end
    end)
  end

