  -- Oak's speech (intro) overrides
  do
    local _oakText = {
      _OakText1 = "Hello there! Welcome to the \11world of POKéMON! \11My name is Oak! People call me \11the POKéMON Professor!",
      _OakText2 = "This world is inhabited by creatures called \11POKéMON!",
      _OakText4 = "For some people, POKéMON are pets. Others use them for fights.",
      _OakText5 = "myself... \11I study POKéMON as a profession.",
      _OakText6 = "First, what is your name?",
      _OakText7 = "{PLAYER}! \11Your very own POKéMON legend is \11about to unfold! \11A wold of dreams and adventures \11with POKéMON awaits! \11Let's go!",
    }
    local _oakDemo = "NIDORINO"
    local _oakNameRival = true
    local _oakRivalIntro = "Right!, So your name is {PLAYER}! \11This is my grand-son. He's been \11He's been your rival since you were a baby. \11... Erm, what is his name again?"
    local _oakRivalConfirm = "That's right! I remember now! His \11name is {RIVAL}!"
    local _oakRivalPresets = {
      "Blue",
      "Gary",
      "Green",
      "Red",
    }
    local _oakPlayerPresets = {
      "Red",
      "Ash",
      "Green",
      "Blue",
    }
    local _oakPlayerPortraitClass = "RED"
    local _oakRivalPortraitClass = "BLUE"
    mod.hooks:wrap("intro.oak_speech.build", function(next, steps, speech)
      if _oakPlayerPresets then
        local pData = speech.game and speech.game.data
        if pData then
          pData.field = pData.field or {}
          pData.field.boot = pData.field.boot or {}
          pData.field.boot.namePresets = pData.field.boot.namePresets or {}
          pData.field.boot.namePresets.player = _oakPlayerPresets
        end
      end
      if _oakPlayerPortraitClass then
        local ppData = (speech.game and speech.game.data) or {}
        local ppMenu = ppData.gen2MenuGfx
        local ppPics = ppMenu and ppMenu.battleHud and ppMenu.battleHud.trainerPics
        local ppPath = ppPics and ppPics[_oakPlayerPortraitClass]
        if ppPath then
          local Assets = require("src.render.Assets")
          local ppOk, ppImg = pcall(Assets.image, ppPath)
          if ppOk and ppImg then
            speech.playerPic = ppImg
            local ppOkP, ppPalettes = pcall(require, "src.world.gen2.Palettes")
            if ppOkP and ppPalettes then
              speech.playerColors = ppPalettes.trainerColors(speech.palettes, _oakPlayerPortraitClass)
            end
          end
        end
      end
      speech.texts = speech.texts or {}
      for k, v in pairs(_oakText) do speech.texts[k] = v end
      if _oakDemo then
        local Assets = require("src.render.Assets")
        local ok, img = pcall(Assets.image,
          "assets/generated/battle/front/" .. _oakDemo:lower() .. ".png")
        if ok and img then
          speech.marillPic = img
          speech.demoSpecies = _oakDemo
          local okP, Palettes = pcall(require, "src.world.gen2.Palettes")
          if okP and Palettes then
            speech.marillColors = Palettes.monColors(speech.palettes, _oakDemo)
          end
        end
      end
      if _oakNameRival then
        local insertAt = #steps + 1
        for i, st in ipairs(steps) do
          if st.id == "name_player" then insertAt = i + 1; break end
        end
        local rData = (speech.game and speech.game.data) or {}
        local rMenuGfx = rData.gen2MenuGfx
        local rTrainerPics = rMenuGfx and rMenuGfx.battleHud
          and rMenuGfx.battleHud.trainerPics
        local rClass = _oakRivalPortraitClass or "RIVAL1"
        local rPortraitPath = rTrainerPics and rTrainerPics[rClass]
        local rOkP, rPalettes = pcall(require, "src.world.gen2.Palettes")
        local rPortraitColors = (rOkP and rPalettes and speech.palettes)
          and rPalettes.trainerColors(speech.palettes, rClass) or nil
        local rSprites = rData.gen2Sprites
        local rRivalOw = rSprites and rSprites.SPRITE_RIVAL
        local rIconPath = rRivalOw and rRivalOw.image
        local rIconColors = (rOkP and rPalettes and rData.gen2Palettes)
          and rPalettes.spritePalette(rData.gen2Palettes, "DAY", rRivalOw) or nil
        local rOkImg, rPortraitImg = pcall(function()
          local Assets = require("src.render.Assets")
          return rPortraitPath and Assets.image(rPortraitPath)
        end)
        if not rOkImg then rPortraitImg = nil end
        table.insert(steps, insertAt, {
          id = "rival_intro", kind = "say", text = _oakRivalIntro,
          pic = { path = rPortraitPath, colors = rPortraitColors },
          reveal = "fade",
        })
        table.insert(steps, insertAt + 1, {
          id = "name_rival", kind = "fn",
          run = function(sp, done)
            local Screens = require("src.ui.Screens")
            local game = sp.game
            local pushed = game and game.stack and Screens.push(game, "Gen2NamePick", {
              font = game.fontData,
              pic = rPortraitImg,
              picColors = rPortraitColors,
              presets = _oakRivalPresets,
              onDone = function(name)
                if game.stack then game.stack:pop() end
                game.save = game.save or {}
                game.save.rival = game.save.rival or {}
                if name and name:gsub(" ", "") ~= "" then
                  game.save.rival.name = name
                else
                  local okV, GameVersion = pcall(require, "src.core.GameVersion")
                  local ver = game.save.version
                    or (okV and GameVersion.get()) or "gold"
                  game.save.rival.name = (ver == "silver") and "GOLD" or "SILVER"
                end
                done()
              end,
            })
            if pushed then
              pushed.namingType = "rival"
              pushed.namingIconPath = rIconPath
              pushed.namingIconColors = rIconColors
            else
              done()
            end
          end,
        })
        table.insert(steps, insertAt + 2, {
          id = "rival_confirm", kind = "say", text = _oakRivalConfirm,
        })
      end
      return next(steps, speech)
    end)
  end

  -- Skip the later (Cherrygrove) rival-naming ask once the intro
  -- already set a real name, instead of asking a confusing second time
  do
    local okW, World = pcall(require, "src.world.gen2.World")
    if okW and World and not World.__betatestNameRivalPatched then
      World.__betatestNameRivalPatched = true
      local _origNameRival = World.nameRival
      World.nameRival = function(self, onDone)
        local save = self.game and self.game.save
        local already = save and save.rival and save.rival.name
        if already and already ~= "" and already ~= "???" then
          if onDone then onDone(already) end
          return
        end
        return _origNameRival(self, onDone)
      end
    end
  end

  do
    local okNP, NamePick = pcall(require, "src.ui.gen2.NamePick")
    if okNP and NamePick and not NamePick.__betatestOpenNamingPatched then
      NamePick.__betatestOpenNamingPatched = true
      local _origOpenNaming = NamePick.openNaming
      function NamePick:openNaming()
        if not self.namingIconPath then return _origOpenNaming(self) end
        local Screens = require("src.ui.Screens")
        local data = self.game and self.game.data or {}
        Screens.push(self.game, "Gen2NamingScreen", {
          type = self.namingType or "player",
          menuGfx = data.gen2MenuGfx,
          iconPath = self.namingIconPath,
          iconColors = self.namingIconColors,
          onDone = function(name)
            self.game.stack:pop() -- the naming screen
            if name and #name > 0 then
              self:choose(name)
            else
              self:choose(self.items[2] or "")
            end
          end,
        })
      end
    end
  end

  -- Player/rival overworld sprite reskin ("Player overworld
  -- sprite"/"Rival overworld sprite" pickers)
  do
    local _oakPlayerSpriteSrc = "SPRITE_RED"
    local _oakRivalSpriteSrc = "SPRITE_BLUE"
    local _oakSpriteFields = { "image", "frames", "palette",
      "paletteId", "spriteType", "walker", "trueColor" }
    local function _oakReskin(sprites, targetId, sourceId)
      if not sourceId then return end
      local src = sprites[sourceId]
      local dst = sprites[targetId]
      if not (src and dst) then return end
      for _, key in ipairs(_oakSpriteFields) do dst[key] = src[key] end
    end
    mod.events:on("mods.loaded", function(ev)
      local data = ev and ev.data
      local sprites = type(data) == "table"
        and (data.gen2Sprites or data.sprites)
      if type(sprites) ~= "table" then return end
      _oakReskin(sprites, "SPRITE_CHRIS", _oakPlayerSpriteSrc)
      _oakReskin(sprites, "SPRITE_RIVAL", _oakRivalSpriteSrc)
    end)
  end

  -- Gold player state sprites (FieldMoves.spriteId)
  do
    local _ps = {
      bike = "SPRITE_RED_BIKE",
      walk = "SPRITE_RED",
    }
    mod.events:on("mods.loaded", function(ev)
      local data = ev and ev.data
      if type(data) ~= "table" then return end
      data.gen2PlayerSprites = data.gen2PlayerSprites or {}
      for k, v in pairs(_ps) do data.gen2PlayerSprites[k] = v end
    end)
  end

  -- Gold player battle / intro pics (gen2MenuGfx + playerPic)
  do
    local _pp = {
    back = mod.path .. "/assets/redb.png",
    demoBack = mod.path .. "/assets/oldmanb.png",
  }
    mod.events:on("mods.loaded", function(ev)
      local data = ev and ev.data
      if type(data) ~= "table" then return end
      local gfx = data.gen2MenuGfx or data.menu_gfx
      if type(gfx) ~= "table" then
        gfx = {}; data.gen2MenuGfx = gfx; data.menu_gfx = gfx
      end
      gfx.battleHud = gfx.battleHud or {}
      if _pp.back then gfx.battleHud.playerBack = _pp.back end
      if _pp.demoBack then gfx.battleHud.dudeBack = _pp.demoBack end
      if _pp.front then data.playerPic = _pp.front end
    end)
  end

  do
    local remap = {
      ["CHIKORITA"] = { species = "BULBASAUR", level = 5 },
      ["CYNDAQUIL"] = { species = "SQUIRTLE", level = 5 },
      ["TOTODILE"] = { species = "CHARMANDER", level = 5 },
    }
    mod.events:on("pokemon.before_give", function(gift)
      local ctx = gift.ctx or {}
      local map = ctx.overworld and ctx.overworld.map
      local mapId = ctx.mapId or (map and map.id)
      if mapId ~= "ELMS_LAB" then return end
      local hit = remap[gift.species]
      if not hit then return end
      gift.species = hit.species
      gift.level = hit.level
    end)
  end

end
